   100  static void
   101  half_to_float_buffer_impl (float* out, const uint16_t* in, int w)
   102  {
   103      while (w >= 8)
   104      {
   105          half_to_float8 (out, in);
   106          out += 8;
   107          in += 8;
   108          w -= 8;
   109      }
   110      switch (w)
   111      {
   112          case 7:
   113              half_to_float4 (out, in);
   114              out[4] = half_to_float (in[4]);
   115              out[5] = half_to_float (in[5]);
   116              out[6] = half_to_float (in[6]);
   117              break;
   118          case 6:
   119              half_to_float4 (out, in);
   120              out[4] = half_to_float (in[4]);
   900  #if EXR_HOST_IS_NOT_LITTLE_ENDIAN
   901              if (pixincrement == 2)
   902              {
   903                  uint16_t*       tmp = (uint16_t*) cdata;
   904                  const uint16_t* src = (const uint16_t*) srcbuffer;
   905                  uint16_t*       end = tmp + w;
   906
   907                  while (tmp < end)
   908                      *tmp++ = one_to_native16 (*src++);
   909              }
   910              else
   911              {
   912                  const uint16_t* src = (const uint16_t*) srcbuffer;
   913                  for (int x = 0; x < w; ++x)
   914                  {
   915                      *((uint16_t*) cdata) = one_to_native16 (*src++);
   916                      cdata += pixincrement;
   917                  }
   918              }
   919  #else
   920              if (pixincrement == 2)
   921              {
   922                  memcpy (cdata, srcbuffer, (size_t) (w) *2);
   923              }
   924              else
   925              {
   926                  const uint16_t* src = (const uint16_t*) srcbuffer;
   927                  for (int x = 0; x < w; ++x)
   928                  {
   929                      *((uint16_t*) cdata) = *src++;
   930                      cdata += pixincrement;
   931                  }
   932              }
   933  #endif
   934              srcbuffer += w * 2;
   935          }
   936      }
   937      return EXR_ERR_SUCCESS;
   938  }
