   940  //static exr_result_t unpack_32bit_3chan (exr_decode_pipeline_t* decode);
   941  //static exr_result_t unpack_32bit_4chan (exr_decode_pipeline_t* decode);
   942
   943  static exr_result_t
   944  unpack_32bit (exr_decode_pipeline_t* decode)
   945  {
   946      /* we know we're unpacking all the channels and there is no subsampling */
   947      const uint8_t* srcbuffer = decode->unpacked_buffer;
   948      uint8_t*       cdata;
   949      int64_t        w, h, pixincrement;
   950      int            chans = decode->channel_count;
   951
   952      h = (int64_t) decode->chunk.height;
   953
   954      for (int64_t y = 0; y < h; ++y)
   955      {
   956          for (int c = 0; c < chans; ++c)
   957          {
   958              exr_coding_channel_info_t* decc = (decode->channels + c);
   959
   960              cdata        = decc->decode_to_ptr;
   961              w            = decc->width;
   962              pixincrement = decc->user_pixel_stride;
   963              cdata += y * (int64_t) decc->user_line_stride;
   964              /* specialize to memcpy if we can */
   965  #if EXR_HOST_IS_NOT_LITTLE_ENDIAN
   966              if (pixincrement == 4)
   967              {
   968                  uint32_t*       tmp = (uint32_t*) cdata;
   969                  const uint32_t* src = (const uint32_t*) srcbuffer;
   970                  uint32_t*       end = tmp + w;
   971
   972                  while (tmp < end)
   973                      *tmp++ = le32toh (*src++);
   974              }
   975              else
   976              {
   977                  const uint32_t* src = (const uint32_t*) srcbuffer;
   978                  for (int64_t x = 0; x < w; ++x)
   979                  {
   980                      *((uint32_t*) cdata) = le32toh (*src++);
   981                      cdata += pixincrement;
   982                  }
   983              }
   984  #else
   985              if (pixincrement == 4)
   986              {
   987                  memcpy (cdata, srcbuffer, (size_t) (w) *4);
   988              }
   989              else
   990              {
   991                  const uint32_t* src = (const uint32_t*) srcbuffer;
   992                  for (int64_t x = 0; x < w; ++x)
   993                  {
   994                      *((uint32_t*) cdata) = *src++;
   995                      cdata += pixincrement;
   996                  }
   997              }
   998  #endif
   999              srcbuffer += w * 4;
  1000          }
  1001      }
  1002      return EXR_ERR_SUCCESS;
  1003  }
