  1005  #define UNPACK_SAMPLES(samps)                                                  \
  1006      switch (decc->data_type)                                                   \
  1007      {                                                                          \
  1008          case EXR_PIXEL_HALF:                                                   \
  1009              switch (decc->user_data_type)                                      \
  1010              {                                                                  \
  1011                  case EXR_PIXEL_HALF: {                                         \
  1012                      const uint16_t* src = (const uint16_t*) srcbuffer;         \
  1013                      for (int s = 0; s < samps; ++s)                            \
  1014                      {                                                          \
  1015                          *((uint16_t*) cdata) = unaligned_load16 (src);         \
  1016                          ++src;                                                 \
  1017                          cdata += ubpc;                                         \
  1018                      }                                                          \
  1019                      break;                                                     \
  1020                  }                                                              \
  1021                  case EXR_PIXEL_FLOAT: {                                        \
  1022                      const uint16_t* src = (const uint16_t*) srcbuffer;         \
  1023                      for (int s = 0; s < samps; ++s)                            \
  1024                      {                                                          \
  1025                          uint16_t cval = unaligned_load16 (src);                \
  1026                          ++src;                                                 \
  1027                          *((float*) cdata) = half_to_float (cval);              \
  1028                          cdata += ubpc;                                         \
  1029                      }                                                          \
  1030                      break;                                                     \
  1031                  }                                                              \
  1032                  case EXR_PIXEL_UINT: {                                         \
  1033                      const uint16_t* src = (const uint16_t*) srcbuffer;         \
  1034                      for (int s = 0; s < samps; ++s)                            \
  1035                      {                                                          \
  1036                          uint16_t cval = unaligned_load16 (src);                \
  1037                          ++src;                                                 \
  1038                          *((uint32_t*) cdata) = half_to_uint (cval);            \
  1039                          cdata += ubpc;                                         \
  1040                      }                                                          \
  1041                      break;                                                     \
  1042                  }                                                              \
  1043                  default: return EXR_ERR_INVALID_ARGUMENT;                      \
  1044              }                                                                  \
  1045              break;                                                             \
